package com.hms.branches;
import com.hms.tenancy.*; import jakarta.validation.Valid; import java.util.*; import org.springframework.http.HttpStatus; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/hospitals/{tenantSlug}/branches") public class BranchController {private final TenantRepository tenants;private final HospitalBranchRepository branches;public BranchController(TenantRepository t,HospitalBranchRepository b){tenants=t;branches=b;} @GetMapping public List<HospitalBranch> list(@PathVariable String tenantSlug){return branches.findAllByTenantIdOrderByNameAsc(tenant(tenantSlug));} @PostMapping @ResponseStatus(HttpStatus.CREATED) public HospitalBranch create(@PathVariable String tenantSlug,@Valid @RequestBody CreateBranchRequest r){return branches.save(new HospitalBranch(tenant(tenantSlug),r));} private UUID tenant(String s){return tenants.findBySlug(s).map(Tenant::getId).orElseThrow(()->new TenantNotFoundException(s));}}
